import React, { useEffect, useRef, useState } from 'react'
import axios from 'axios'

interface PacketItem {
  id: number
  timestamp: string
  srcIp: string
  dstIp: string
  protocol: string
  length: number
  prediction: string
  confidence: number
}

const interfaces = ['eth0', 'wlan0', 'any', 'en0']

const LiveCapturePanel: React.FC = () => {
  const [isCapturing, setIsCapturing] = useState(false)
  const [selectedInterface, setSelectedInterface] = useState('eth0')
  const [packets, setPackets] = useState<PacketItem[]>([])
  const [message, setMessage] = useState('等待开始')
  const [status, setStatus] = useState('停止')
  const [error, setError] = useState<string | null>(null)
  const [stats, setStats] = useState({ total: 0, normal: 0, anomaly: 0, unknown: 0 })
  const nextPacketId = useRef(1)
  const lastTimestampRef = useRef('')

  useEffect(() => {
    let interval: number | undefined
    if (isCapturing) {
      interval = window.setInterval(async () => {
        try {
          const response = await axios.get('/api/capture/status')
          const data = response.data?.data
          if (!data) {
            return
          }

          setStatus(data.isRunning ? '抓包中' : '已停止')
          setMessage(`最新检测: ${data.prediction}`)

          const flow = data.flowDetail
          if (flow && flow.timestamp && flow.timestamp !== lastTimestampRef.current) {
            lastTimestampRef.current = flow.timestamp
            const packet: PacketItem = {
              id: nextPacketId.current++,
              timestamp: flow.timestamp,
              srcIp: flow.src_ip || 'N/A',
              dstIp: flow.dst_ip || 'N/A',
              protocol: flow.protocol || 'OTHER',
              length: flow.packet_length || 0,
              prediction: flow.prediction || data.prediction || 'UNKNOWN',
              confidence: flow.confidence || 0
            }
            setPackets((prev) => [packet, ...prev].slice(0, 100))
            setStats((prev) => {
              const normal = packet.prediction === 'BENIGN' ? prev.normal + 1 : prev.normal
              const anomaly = packet.prediction !== 'BENIGN' && packet.prediction !== 'UNKNOWN' ? prev.anomaly + 1 : prev.anomaly
              const unknown = packet.prediction === 'UNKNOWN' ? prev.unknown + 1 : prev.unknown
              return { total: prev.total + 1, normal, anomaly, unknown }
            })
          }
        } catch (err) {
          setError('无法获取抓包状态，请检查后端。')
          setIsCapturing(false)
        }
      }, 1000)
    }

    return () => {
      if (interval) {
        window.clearInterval(interval)
      }
    }
  }, [isCapturing])

  const handleStartCapture = async () => {
    setError(null)

    try {
      const response = await axios.post('/api/capture/start', { interface: selectedInterface })
      if (response.data?.success) {
        setIsCapturing(true)
        setStatus('抓包中')
        setMessage(response.data.message || '开始抓包')
        setPackets([])
        setStats({ total: 0, normal: 0, anomaly: 0, unknown: 0 })
        lastTimestampRef.current = ''
      } else {
        setError(response.data?.error || '启动抓包失败')
      }
    } catch (err) {
      setError('启动抓包请求失败，请检查后端服务器。')
    }
  }

  const handleStopCapture = async () => {
    try {
      await axios.post('/api/capture/stop')
      setIsCapturing(false)
      setStatus('已停止')
      setMessage('抓包已停止')
    } catch (err) {
      setError('停止抓包请求失败。')
    }
  }

  return (
    <div>
      <h2>实时抓包检测</h2>
      <div style={{ marginBottom: 16 }}>
        <label>
          抓包接口:
          <select
            value={selectedInterface}
            onChange={(e) => setSelectedInterface(e.target.value)}
            disabled={isCapturing}
            style={{ marginLeft: 8 }}
          >
            {interfaces.map((iface) => (
              <option key={iface} value={iface}>
                {iface}
              </option>
            ))}
          </select>
        </label>
        <button onClick={handleStartCapture} disabled={isCapturing} style={{ marginLeft: 16 }}>
          开始抓包
        </button>
        <button onClick={handleStopCapture} disabled={!isCapturing} style={{ marginLeft: 8 }}>
          停止抓包
        </button>
      </div>

      <div style={{ marginBottom: 16 }}>
        <strong>状态: </strong> {status}
        <br />
        <strong>检测信息: </strong> {message}
        {error && (
          <div style={{ color: 'red', marginTop: 8 }}>{error}</div>
        )}
      </div>

      <div style={{ marginBottom: 16 }}>
        <strong>统计:</strong>
        <div>总计包数: {stats.total}</div>
        <div>正常: {stats.normal}</div>
        <div>异常: {stats.anomaly}</div>
        <div>未知: {stats.unknown}</div>
      </div>

      <div>
        <h3>最近检测结果</h3>
        <div style={{ maxHeight: 340, overflowY: 'auto', border: '1px solid #ddd', padding: 12 }}>
          {packets.length === 0 ? (
            <div>等待检测结果...</div>
          ) : (
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr>
                  <th style={{ textAlign: 'left', padding: '6px 8px' }}>时间</th>
                  <th style={{ textAlign: 'left', padding: '6px 8px' }}>源 IP</th>
                  <th style={{ textAlign: 'left', padding: '6px 8px' }}>目的 IP</th>
                  <th style={{ textAlign: 'left', padding: '6px 8px' }}>协议</th>
                  <th style={{ textAlign: 'left', padding: '6px 8px' }}>结果</th>
                  <th style={{ textAlign: 'left', padding: '6px 8px' }}>置信度</th>
                </tr>
              </thead>
              <tbody>
                {packets.map((packet) => (
                  <tr key={packet.id}>
                    <td style={{ padding: '6px 8px' }}>{packet.timestamp}</td>
                    <td style={{ padding: '6px 8px' }}>{packet.srcIp}</td>
                    <td style={{ padding: '6px 8px' }}>{packet.dstIp}</td>
                    <td style={{ padding: '6px 8px' }}>{packet.protocol}</td>
                    <td style={{ padding: '6px 8px' }}>{packet.prediction}</td>
                    <td style={{ padding: '6px 8px' }}>{packet.confidence.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  )
}

export default LiveCapturePanel
